pages.css:
.cover{height:100%;box-sizing:border-box;position:relative;overflow:hidden;
 background:linear-gradient(160deg,#1a1a2e 0%,#242449 55%,#E2571C 230%);
 font-family:'Poppins','Segoe UI',Arial,sans-serif;color:#fff;
 display:flex;flex-direction:column;justify-content:space-between;padding:56px 54px 44px;}
.cov-shape1{position:absolute;top:-90px;right:-90px;width:320px;height:320px;border-radius:50%;
 background:rgba(245,166,35,0.18);}
.cov-shape2{position:absolute;bottom:-120px;left:-80px;width:380px;height:380px;border-radius:50%;
 background:rgba(255,255,255,0.06);}
.cov-shape3{position:absolute;top:280px;right:60px;width:120px;height:120px;border-radius:24px;
 transform:rotate(18deg);background:rgba(245,166,35,0.14);}
.cov-eyebrow{font-size:17.5px;font-weight:800;letter-spacing:3px;color:#F5A623;text-transform:uppercase;
 position:relative;z-index:2;}
.cov-series{font-size:46px;font-weight:800;margin-top:6px;letter-spacing:1px;position:relative;z-index:2;}
.cov-subject{font-size:28px;font-weight:700;color:#F5A623;margin-top:14px;position:relative;z-index:2;}
.cov-grade{display:inline-block;margin-top:18px;background:#F5A623;color:#1a1a2e;font-weight:800;
 font-size:28px;padding:8px 22px;border-radius:30px;position:relative;z-index:2;}
.cov-letters{position:relative;z-index:2;display:flex;gap:14px;margin-top:34px;}
.cov-letter{width:54px;height:54px;border:3px solid rgba(255,255,255,0.35);border-radius:12px;
 display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:800;
 background:rgba(255,255,255,0.06);}
.cov-footer{position:relative;z-index:2;border-top:1px solid rgba(255,255,255,0.25);padding-top:18px;}
.cov-author{font-size:17px;font-weight:700;}
.cov-inst{font-size:17.5px;color:rgba(255,255,255,0.75);margin-top:3px;}

.wb-body{padding:12px 4px 2px;height:100%;box-sizing:border-box;font-family:'Poppins','Segoe UI',Arial,sans-serif;color:#1a1a1a;display:flex;flex-direction:column;gap:9px;overflow:hidden;}
.wb-pagetitle{font-size:28px;font-weight:800;color:#1a1a2e;border-bottom:3px solid #F5A623;padding-bottom:6px;margin-bottom:2px;}
.wb-para{font-size:17px;line-height:1.55;font-weight:600;color:#1a1a1a;margin:0;}
.wb-subhead{font-size:18px;font-weight:800;color:#E2571C;margin-top:2px;}
.wb-note{border:2px dashed #E2571C;border-radius:8px;padding:9px 13px;background:#fff8f3;font-size:17px;line-height:1.45;}
.wb-chiplist{display:flex;flex-wrap:wrap;gap:7px;padding:3px 2px;justify-content:center;}
.wb-chip{border:2px solid #1a1a2e;border-radius:16px;padding:5px 12px;font-size:17.5px;font-weight:800;color:#1a1a2e;background:#fff;}
.wb-tablewrap{border:2px solid #E2571C;border-radius:8px;overflow:hidden;}
.wb-table{width:100%;border-collapse:collapse;font-size:18px;}
.wb-table th{background:#E2571C;color:#fff;padding:6px 10px;font-weight:700;text-align:left;}
.wb-table td{padding:6px 10px;border-top:1px solid #f0c9a8;border-right:1px solid #f0c9a8;font-weight:600;}
.wb-table td:last-child{border-right:none;}
.wb-bullets{margin:0;padding-left:18px;font-size:17px;line-height:1.55;font-weight:600;color:#1a1a1a;}
.wb-bullets li{margin-bottom:4px;}
.rh-footer{position:absolute;left:0;right:0;bottom:0;height:34px;display:flex;align-items:center;justify-content:space-between;padding:0 26px;font-family:'Poppins','Segoe UI',Arial,sans-serif;font-size:11.5px;font-weight:700;color:#9a9a9a;border-top:2px solid #F5A623;box-sizing:border-box;background:#fff;}
.rh-footer .rh-dot{color:#E2571C;}

